{"op":"define","frontend":"flow","source":"word customer.discounted-balance(customer: Customer) -> Money {
    effects none
    doc "Applies a 10 percent discount only when the raw customer kind is exactly premium, truncating fractional minor units toward zero."
    if customer::premium?(customer) {
        let balance = Money::value(customer::balance(customer))
        let tens = ::divide(balance, 10)
        let remainder = ::subtract(balance, ::multiply(tens, 10))
        let whole = ::multiply(tens, 9)
        let fraction = ::divide(::multiply(remainder, 9), 10)
        Money::new(::add(whole, fraction))
    } else {
        customer::balance(customer)
    }
}

